"""SCRIPTED demonstrations for tests and the headless demo. These are generated by code that drives a host's
"user move" API; they are not recordings of a person. The motion is deliberately goal-dependent (longer moves
ease in more and run faster) so that a goal-conditioned learner has something real to learn."""
from __future__ import annotations

import math
import random


def shape(phase: float, a: float) -> float:
    return phase ** a / (phase ** a + (1 - phase) ** a) if 0 < phase < 1 else float(phase >= 1)


def scripted_move(host, object_id, joint, start, goal, span, *, rng: random.Random, rate_hz=30.0, t0=0.0, recorder=None):
    d = abs(goal - start) / span
    a = 1.3 + 2.4 * d                       # easing depends on distance
    T = 0.6 + 2.2 * d ** 0.7                # duration grows sub-linearly with distance
    T *= 1 + rng.uniform(-0.05, 0.05)
    host.user_set_joint(object_id, joint, start, t=t0, event="sample")
    n = max(3, int(T * rate_hz))
    for k in range(1, n + 1):
        ph = k / n
        noise = rng.gauss(0, 0.004) * math.sin(math.pi * ph)
        v = start + (goal - start) * min(1.0, max(0.0, shape(ph, a) + noise))
        host.user_set_joint(object_id, joint, v, t=t0 + ph * T, event="sample")
    host.user_set_joint(object_id, joint, goal, t=t0 + T + 1e-3, event="edit")
    return T


def record_scripted_demos(host, snapshot, object_id, joint_name, pairs, *, seed=0):
    """Record one Demonstration per (start, goal) pair through the real Recorder + host event path."""
    from tw_scene import find_joint, find_object
    from .recorder import Recorder
    rng = random.Random(seed)
    j = find_joint(find_object(snapshot, object_id), joint_name)
    span = j["upper"] - j["lower"]
    demos = []
    t = 0.0
    for i, (s, g) in enumerate(pairs):
        rec = Recorder(snapshot, object_id, joint_name, context={"source": "scripted", "index": i})
        unsub = host.subscribe_changes(rec.on_change)
        rec.start()
        T = scripted_move(host, object_id, joint_name, s, g, span, rng=rng, t0=t)
        unsub()
        demos.append(rec.stop(demo_id=f"demo-{object_id}-{i:03d}"))
        t += T + 1.0
    return demos
